def breakPalindrome(palindrome):
    s = list(palindrome)
    n = len(s)
    if n == 1:
        return ""
    for i in range(n // 2):
        if s[i] != 'a':
            s[i] = 'a'
            return ''.join(s)
    s[-1] = 'b'
